mapper.select:
SELECT bi.id, bi.tenant_id AS tenantId, bi.position_id AS positionId, bi.title, bi.subtitle, bi.description, bi.tag_text AS tagText, bi.image_url AS imageUrl, bi.jump_type AS jumpType, bi.jump_value AS jumpValue, bi.ext_json AS extJson, bi.sort, bi.status, bi.publish_start_time AS publishStartTime, bi.publish_end_time AS publishEndTime, bi.remark, bi.create_user AS createUser, bi.create_dept AS createDept, bi.create_time AS createTime, bi.update_user AS updateUser, bi.update_time AS updateTime, bi.is_deleted AS isDeleted, bp.code AS positionCode, bp.name AS positionName FROM ldqc_banner_item bi LEFT JOIN ldqc_banner_position bp ON bp.id = bi.position_id AND bp.is_deleted = 0 WHERE bi.is_deleted = 0
AND bi.position_id = #{bannerItem.positionId}
AND bp.code LIKE CONCAT('%', #{bannerItem.positionCode}, '%')
AND bp.name LIKE CONCAT('%', #{bannerItem.positionName}, '%')
AND bi.title LIKE CONCAT('%', #{bannerItem.title}, '%')
AND bi.jump_type = #{bannerItem.jumpType}
AND bi.status = #{bannerItem.status}
ORDER BY bi.sort ASC, bi.create_time DESC
